var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that the original behavior is preserved
    assert.strictEqual(ms('1y'), 31557600000);
    assert.strictEqual(ms('1w'), 604800000);
    assert.strictEqual(ms('1d'), 86400000);
    assert.strictEqual(ms('1h'), 3600000);
    assert.strictEqual(ms('1m'), 60000);
    assert.strictEqual(ms('1s'), 1000);
    assert.strictEqual(ms('1ms'), 1);

    // Test that the new behavior doesn't break parsing
    assert.strictEqual(ms('1 year'), 31557600000);
    assert.strictEqual(ms('1 week'), 604800000);
    assert.strictEqual(ms('1 day'), 86400000);
    assert.strictEqual(ms('1 hour'), 3600000);
    assert.strictEqual(ms('1 minute'), 60000);
    assert.strictEqual(ms('1 second'), 1000);
    assert.strictEqual(ms('1 millisecond'), 1);

    // Test case-insensitivity
    assert.strictEqual(ms('1Y'), 31557600000);
    assert.strictEqual(ms('1W'), 604800000);
    assert.strictEqual(ms('1D'), 86400000);
    assert.strictEqual(ms('1H'), 3600000);
    assert.strictEqual(ms('1M'), 60000);
    assert.strictEqual(ms('1S'), 1000);
    assert.strictEqual(ms('1MS'), 1);

    // Test invalid input
    assert.strictEqual(ms('invalid'), undefined);
    assert.strictEqual(ms(''), undefined);
    assert.strictEqual(ms(null), undefined);
    assert.strictEqual(ms(NaN), undefined);
    assert.strictEqual(ms(Infinity), undefined);
  });
});

